def distributeCookies(cookies: list[int], k: int) -> int:
    n = len(cookies)
    submask_sum = [0] * (1 << n)
    for mask in range(1 << n):
        for i in range(n):
            if mask & (1 << i):
                submask_sum[mask] += cookies[i]
    dp = submask_sum[:]
    for child in range(2, k + 1):
        nxt_dp = [float('inf')] * (1 << n)
        for mask in range(1 << n):
            submask = mask
            while submask > 0:
                val = max(dp[mask ^ submask], submask_sum[submask])
                if val < nxt_dp[mask]: nxt_dp[mask] = val
                submask = (submask - 1) & mask
        dp = nxt_dp
    return dp[(1 << n) - 1]

